import type { BlogArticleFaq } from '../../../types/blog';

export const BODY: string = "\n<p>Bir görselin kontrastını ayarlamak dakikalar sürer. Program kurmazsınız, fotoğrafınız cihazınızdan ayrılmaz ve sonunda canlı bir görsel indirirsiniz.</p>\n<p>Bu yazı, işlemi beş adımda anlatıyor. İster düz fotoğraf canlandırın ister sert fotoğraf yumuşatın, adımlar aynıdır.</p>\n<p>Sonunda kaydırıcıyı nasıl kullanacağınızı, gölgeleri ve parlak alanları nasıl kontrol edeceğinizi öğreneceksiniz.</p>\n<h2 id=\"before-you-start\">Başlamadan önce: fotoğrafı teşhis edin</h2>\n<p>Önce fotoğrafa bakın. Düz mü, sert mi, koyu mu? Teşhis, ayarı belirler.</p>\n<p>Orijinal fotoğrafın bir yedeğini alın. Düzenlenen fotoğraf ayrı bir dosyadır; orijinal, güvenlik ağınızdır.</p>\n<p>Kontrastı ayarlamadan önce fotoğrafın amacını düşünün; portre, manzara ve belge için gereken kontrast farklıdır.</p>\n<h2 id=\"step-by-step\">Kontrastı beş adımda ayarlamak</h2>\n<p>Önce kontrast aracını açıp fotoğrafı yükleyin. Önizlemede görselin bütününe bakın.</p>\n<p>Sonra kaydırıcıyı hareket ettirin ve sonucu izleyin. Karşılaştırma modunda farkı görün.</p>\n<p>Son olarak gölgeleri ve parlak alanları kontrol edip indirin. Önizlemeyi atlamayın.</p>\n<ol>\n<li>Kontrast aracını açın ve fotoğrafınızı yükleyin.</li>\n<li>Kaydırıcıyı hareket ettirin; düz fotoğraf için +10 ile +20 arası.</li>\n<li>Hızlı ön ayarı deneyin ya da karşılaştırma moduyla farkı görün.</li>\n<li>Gölgeleri ve parlak alanları kontrol edin.</li>\n<li>Sonucu önizlemede kontrol edip indirin.</li>\n</ol>\n<h2 id=\"using-the-slider\">Kontrast kaydırıcısını kullanmak</h2>\n<p>Kontrast kaydırıcısı -100 ile +100 arasında çalışır. Sıfır değeri, orijinal görseldir.</p>\n<p>Kontrastı azar azar artırın; +10 ile +20 arası, çoğu düz fotoğraf için yeterlidir.</p>\n<p>Aşırı değerler, fotoğrafı bozar. +50'nin üzeri, parlak alanları beyazlatır.</p>\n<h2 id=\"using-quick-presets\">Hızlı ön ayarları kullanmak</h2>\n<p>Hazır ön ayarlardan yararlanın; hafif güç, orta güç ve yumuşat seçenekleri, yaygın düzeltmeleri tek tıkla yapar.</p>\n<p>Ön ayarı uygulayıp kaydırıcıyla ince ayar yapın. Ön ayar başlangıçtır; son ayar sizindir.</p>\n<p>Ön ayarınızı kaydedin. Aynı ayarı tekrar tekrar yapıyorsanız tek tıkla uygulayın.</p>\n<h2 id=\"using-compare-modes\">Karşılaştırma modlarını kullanmak</h2>\n<p>Karşılaştırma modunda orijinal ve düzenlenen sürüm yan yana görünür. Farkı anında görürsünüz.</p>\n<p>Bölünmüş görünümde fotoğrafın yarısı orijinal kalır. Kaydırıcıyı oynatarak karşılaştırın.</p>\n<p>Karşılaştırma, fazla düzenlemeyi engeller. Farkı gördükçe kaydırıcıyı bırakırsınız.</p>\n<h2 id=\"boosting-a-flat-photo\">Düz bir fotoğrafı canlandırmak</h2>\n<p>Düz fotoğrafta kontrastı +10 ile +20 arasında tutun. Sisli fotoğraf canlanır.</p>\n<p>Renkleri kontrol edin. Kontrast artınca renkler doygun görünür.</p>\n<p>Kontrastı artırdıktan sonra gökyüzüne bakın; fazla kontrast, bulutları beyaza boyar.</p>\n<h2 id=\"softening-a-harsh-photo\">Sert bir fotoğrafı yumuşatmak</h2>\n<p>Sert fotoğrafta negatif kontrast kullanın. -10 ile -20 arası, gölgeleri yumuşatır.</p>\n<p>Öğle güneşinde çekilen portrelerde kontrastı eksiye çekin; sert gölgeler yumuşar.</p>\n<p>Negatif kontrastı abartmayın. Fazlası, fotoğrafı sisli gösterir.</p>\n<h2 id=\"fixing-a-screenshot\">Soluk bir ekran görüntüsünü düzeltmek</h2>\n<p>Soluk ekran görüntülerinde kontrastı artırın. Yazılar, zeminden ayrılır.</p>\n<p>Kontrastı +10 ile +20 arasında tutun. Yazılar keskin kalmalıdır.</p>\n<p>Ekran görüntüleri için PNG kullanın. Metin, kayıpsız formatta okunaklı kalır.</p>\n<h2 id=\"checking-shadows-highlights\">Gölgeleri ve parlak alanları kontrol etmek</h2>\n<p>Gölgeleri kontrol edin. Fazla kontrast, koyu ayrıntıyı siyaha çevirir.</p>\n<p>Parlak alanları kontrol edin. Fazla kontrast, parlak ayrıntıyı beyaza çevirir.</p>\n<p>Histogramı izleyin. Beyaz ve siyah yığılma olmamalıdır.</p>\n<h2 id=\"previewing\">İndirmeden önce önizleme</h2>\n<p>Her zaman önizlemeyi kontrol edin. Kontrast ve parlaklık doğru olmalıdır.</p>\n<p>Karşılaştırma görünümüyle orijinal ve düzenlenen sürümü yan yana inceleyin. Fark doğal mı?</p>\n<p>Şüphede kalırsanız kontrastı azaltın. Hafif düzeltme, aşırı düzeltmeden her zaman iyidir.</p>\n<h2 id=\"choosing-export-format\">Dışa aktarma formatını seçmek</h2>\n<p>Fotoğrafları JPG biçiminde indirin. Hafif dosyalar her platformda görüntülenir.</p>\n<p>Saydam alanlar için PNG seçin. JPG, bu alanları beyaz doldurur.</p>\n<p>Kaliteyi yüzde 85-90 tutun. Dosya hafifler, görsel kalite korunur.</p>\n<h2 id=\"adjusting-on-mobile\">Telefon ve tablette kontrast ayarlamak</h2>\n<p>Kontrast aracını telefon tarayıcısında açın, fotoğrafı yükleyin ve kaydırıcıyı hareket ettirin.</p>\n<p>Telefonda küçük ayarlar zorlaşır. Hassas kontrast ayarı için bilgisayarı kullanın.</p>\n<p>Dosyalar İndirilenler klasörüne gider. Bulamazsanız tarayıcının indirme geçmişini açın.</p>\n<h2 id=\"troubleshooting\">Kontrastla yaygın sorunları çözmek</h2>\n<p>Parlak alanlar beyazlaşıyorsa kontrastı azaltın. Fazla kontrast, ayrıntıyı keser.</p>\n<p>Gölgeler kararıyorsa kontrastı azaltın. Koyu ayrıntı kaybolmamalıdır.</p>\n<p>Kaydırıcı çalışmıyorsa sayfayı yenileyin. Tarayıcı sorunu genellikle yenilemeyle çözülür.</p>\n<h2 id=\"contrast-plus-brightness\">Kontrast ve parlaklık: yaygın ikili</h2>\n<p>Parlaklık aydınlatır, kontrast derinlik verir. İkisi birlikte fotoğrafı canlandırır.</p>\n<p>Önce parlaklık, sonra kontrast ayarlayın. Sıralama, doğru dengeyi bulmanızı sağlar.</p>\n<p>İkisini birlikte abartmayın. Aşırı parlaklıkla kontrast, fotoğrafı yapay gösterir.</p>\n<h2 id=\"saving-settings\">Ayarları bir dahaki sefer için kaydetmek</h2>\n<p>Bulduğunuz kontrast değerini bir kenara yazın; aynı düzeltmeyi tekrarlıyorsanız sayıları kaydetmek işi hızlandırır.</p>\n<p>İşe yarayan kontrast ayarını ön ayar olarak kaydedin; aynı düzeltmeyi tek tıkla tekrar uygularsınız.</p>\n<p>Ayarları ekiple paylaşın. Tutarlı düzenleme markayı güçlendirir.</p>\n<h2 id=\"quick-tips\">Daha iyi kontrast için hızlı ipuçları</h2>\n<p>Kontrastı küçük adımlarla yükseltin; +10 iyi bir başlangıçtır, gerekirse azar azar artırın.</p>\n<p>Kontrastı ayarlarken karşılaştırma modundan yararlanın; farkı gördükçe ayarı doğru noktada bırakırsınız.</p>\n<p>Kontrast düzenlemesinde orijinali elinizde tutun; düzenlenen sürümü ayrı bir dosya olarak kaydedin.</p>\n<h2 id=\"contrast-for-product-photo\">Ürün fotoğrafına kontrast eklemek</h2>\n<p>Ürün fotoğraflarında kontrastı +10 ile +15 arasında tutun. Ürün canlı görünmelidir.</p>\n<p>Renkleri kontrol edin. Kontrast artınca renkler doygun görünür.</p>\n<p>Tüm ürün görsellerinde aynı ayarı kullanın. Tutarlı liste, mağazada profesyonel görünür.</p>\n<p>Adım adım ilerleyin ve her fotoğrafı indirmeden önce kontrol edin. Kılavuzun tamamı için <a href=\"/tr/blog/gorsel-kontrast-duzenleyici-rehberi\">Kontrast düzenleyici kılavuzuna</a> bakın; karşılaştırma için <a href=\"/tr/blog/parlaklik-vs-pozlama-vs-kontrast\">parlaklık, pozlama ve kontrast karşılaştırması</a> yardımcı olur. Parlaklık için <a href=\"/tr/gorsel-parlaklik-ayarla\">görsel parlaklık düzenleyici</a> hazırdır; araç ise <a href=\"/tr/gorsel-kontrast-ayarla\">görsel kontrast düzenleyici</a> sayfasındadır.</p>\n";

export const FAQS: BlogArticleFaq[] = [{"question":"Telefonda bir fotoğrafa kontrast nasıl eklerim?","answer":"Kontrast aracını telefon tarayıcısında açın, fotoğrafı yükleyin ve kaydırıcıyı +10 ile +20 arasına hareket ettirin. Karşılaştırma moduyla farkı görün. Hassas ayar için bilgisayarı tercih edin."},{"question":"Sisli bir manzara için hangi kontrast değerini kullanmalıyım?","answer":"+10 ile +20 arası genellikle yeterlidir. Sisli fotoğraf canlanır. Gökyüzünü kontrol edin; fazla kontrast bulutları beyazlatır. Küçük adımlarla ayarlayın."},{"question":"Sert bir portreyi yumuşatmak için kontrastı azaltabilir miyim?","answer":"Evet. Negatif kontrast kullanın; -10 ile -20 arası gölgeleri yumuşatır. Öğle güneşi altında çekilen portrelerde negatif kontrast idealdir. Fazlası fotoğrafı sisli gösterir."},{"question":"Fotoğrafımın parlak alanları kontrast ekledikten sonra neden beyaz oluyor?","answer":"Çünkü kontrastı fazla artırdınız; parlak ayrıntı beyaza kesildi. Kontrastı azaltın ve histogramı izleyin; beyaz yığılma olmamalıdır. +20'nin üzeri çoğu fotoğrafta risklidir."},{"question":"Kontrastı mı parlaklığı mı önce ayarlamalıyım?","answer":"Önce parlaklığı ayarlayın, sonra kontrastı. Parlaklık genel aydınlığı düzeltir; kontrast derinlik verir. Önce kontrast artırmak, koyu alanları daha da karartır."},{"question":"İndirdikten sonra kontrast değişikliğini geri alabilir miyim?","answer":"Hayır, indirilen dosya geri alınamaz. Bu yüzden orijinal fotoğrafı saklayın. Orijinal dururken istediğiniz zaman yeniden düzenleyebilirsiniz."}];
